# frozen_string_literal: true

module FieldStruct
  # Writes RBS for classes that inherit FieldStruct::Base (FS-B127 to FS-B130). The types describe a valid
  # instance, so a required field's reader has no +?+ and every writer accepts +nil+.
  module RBS
    # The comment header every generated signature starts with.
    # @return [::String]
    HEADER = <<~TEXT
      # Generated by FieldStruct::RBS. Types describe a valid instance: an
      # invalid one (a required field left unset, or a :keep_raw coercion
      # failure holding the raw input) can hold other values. Check valid?.
    TEXT

    GENERIC_ARGUMENTS = { ::Array => '::Array[untyped]', ::Hash => '::Hash[untyped, untyped]', ::Range => '::Range[untyped]' }.freeze
    SCALARS = {
      ::String => '::String', ::Symbol => '::Symbol', ::Integer => '::Integer', ::Float => '::Float', ::BigDecimal => '::BigDecimal',
      ::Date => '::Date', ::Time => '::Time', ::DateTime => '::DateTime'
    }.freeze
    OPERATORS = /[|&^]/
    private_constant :GENERIC_ARGUMENTS, :SCALARS, :OPERATORS

    class << self
      # Builds the signature text for one class: a comment header, then the class inside +module+ blocks for its namespace.
      #
      # @param klass [Class] a strict subclass of +FieldStruct::Base+ with a name
      # @return [String] RBS source ending in a newline
      # @raise [ArgumentError] for anything else, or an anonymous class
      def generate(klass)
        unless klass.is_a?(::Class) && klass < FieldStruct::Base
          raise ::ArgumentError, "FieldStruct::RBS.generate expects a FieldStruct::Base subclass, got #{klass.inspect}"
        end
        raise ::ArgumentError, 'cannot generate RBS for an anonymous class' if klass.name.nil?

        segments = klass.name.split('::')
        body = class_lines(klass, segments.last)
        wrapped = segments[0...-1].each_with_index.reverse_each.reduce(body) do |lines, (segment, depth)|
          wrap(lines, segment, namespace_keyword(segments[0..depth]))
        end
        "#{HEADER}#{wrapped.join("\n")}\n"
      end

      # The RBS type of one field's reader (or writer).
      #
      # @param field [FieldStruct::Field]
      # @param nullable [Boolean, nil] +nil+ means nullable unless the field is required
      # @return [String]
      # @raise [ArgumentError] for a non-Field, or a reference to an anonymous class
      def type_for(field, nullable: nil)
        unless field.is_a?(FieldStruct::Field)
          raise ::ArgumentError, "FieldStruct::RBS.type_for expects a FieldStruct::Field (e.g. User.metadata[:name]), got #{field.inspect}"
        end

        nullable = !field.required? if nullable.nil?
        base = field.rbs_type ? normalize(field.rbs_type) : derive(field.type_instance, field.options)
        nullable ? nullify(base) : base
      end

      private

      def class_lines(klass, short_name)
        parent = klass.superclass
        raise ::ArgumentError, 'cannot generate RBS for an anonymous class' if parent.name.nil?

        lines = ["class #{short_name} < ::#{parent.name}"]
        entries = own_fields(klass, parent).map { |field| field_lines(field) }
        lines.concat(entries.flat_map.with_index { |entry, index| index.zero? ? entry : ['', *entry] })
        lines << 'end'
      end

      def own_fields(klass, parent)
        inherited = parent < FieldStruct::Base ? parent.metadata : nil
        klass.metadata.reject { |field| inherited && inherited[field.name].equal?(field) }
      end

      def field_lines(field)
        writer = type_for(field, nullable: true)
        ["  attr_reader #{field.name}: #{type_for(field)}", "  def #{field.name}=: (#{writer} value) -> #{writer}"]
      end

      def wrap(lines, segment, keyword)
        ["#{keyword} #{segment}", *lines.map { |line| line.empty? ? line : "  #{line}" }, 'end']
      end

      def namespace_keyword(path)
        Object.const_get(path.join('::')).is_a?(::Class) ? 'class' : 'module'
      rescue ::NameError
        'module'
      end

      def derive(type, options = {})
        override = type.rbs_type
        return normalize(override) if override

        case type
        when Types::Nested then class_name(type.struct_class)
        when Types::Array then array_type(options[:of_type])
        when Types::Union then union_type(type)
        else ruby_types(type.ruby_type)
        end
      end

      def array_type(of_type)
        return '::Array[untyped]' if of_type.nil?

        element = of_type.is_a?(::Class) ? of_type.new : of_type
        inner = derive(element)
        inner = nullify(inner) unless element.is_a?(Types::Nested)
        "::Array[#{inner}]"
      end

      def union_type(union)
        members = union.member_types.map { |member| derive(member) }.uniq
        return 'untyped' if members.empty? || members.include?('untyped')

        members.size == 1 ? members.first : "(#{members.join(' | ')})"
      end

      def ruby_types(classes)
        names = [classes].flatten.map { |klass| class_type(klass) }.uniq
        names = collapse_booleans(names)
        return 'untyped' if names.include?('untyped')

        names.size == 1 ? names.first : "(#{names.join(' | ')})"
      end

      def collapse_booleans(names)
        return names unless names.include?('::TrueClass') && names.include?('::FalseClass')

        position = names.index('::TrueClass')
        (names - %w[::TrueClass ::FalseClass]).insert(position, 'bool')
      end

      def class_type(klass)
        return 'untyped' if klass == ::Object
        return SCALARS[klass] if SCALARS.key?(klass)
        return GENERIC_ARGUMENTS[klass] if GENERIC_ARGUMENTS.key?(klass)

        class_name(klass)
      end

      def class_name(klass)
        raise ::ArgumentError, 'FieldStruct::RBS cannot name an anonymous class; assign it to a constant' if klass.name.nil?

        "::#{klass.name}"
      end

      # Strips an override and parenthesizes it when it holds an operator outside one wrapped group.
      def normalize(text)
        text = text.strip
        return text unless text.match?(OPERATORS)

        one_group?(text.delete_suffix('?')) ? text : "(#{text})"
      end

      def one_group?(text)
        return false unless text.start_with?('(') && text.end_with?(')')

        depth = 0
        text.each_char.with_index do |char, index|
          depth += { '(' => 1, ')' => -1 }.fetch(char, 0)
          return false if depth.zero? && index < text.length - 1
        end
        true
      end

      def nullify(type)
        type == 'untyped' || type.end_with?('?') ? type : "#{type}?"
      end
    end
  end
end
